import { useEffect, useMemo, useRef, useState } from 'react'
import type * as Leaflet from 'leaflet'
import { MapPin } from 'lucide-react'
import type { Place } from '@/types'
import { cn } from '@/lib/cn'
import { Button } from '@/components/ui/Button'

interface PlaceMapProps {
  places: Place[]
  selectedPlaceId?: string | null
  onSelectPlace?: (id: string) => void
  className?: string
}

type MapSession = { leaflet: typeof Leaflet; map: Leaflet.Map }
const TILE_URL = import.meta.env.VITE_MAP_TILE_URL?.trim() || 'https://tile.openstreetmap.org/{z}/{x}/{y}.png'
const ATTRIBUTION = import.meta.env.VITE_MAP_ATTRIBUTION?.trim() ||
  '&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap contributors</a>'

export function PlaceMap({ places, selectedPlaceId, onSelectPlace, className }: PlaceMapProps) {
  const containerRef = useRef<HTMLDivElement>(null)
  const mapRef = useRef<Leaflet.Map | null>(null)
  const tileLayerRef = useRef<Leaflet.TileLayer | null>(null)
  const markerLayerRef = useRef<Leaflet.LayerGroup | null>(null)
  const [session, setSession] = useState<MapSession | null>(null)
  const [initError, setInitError] = useState(false)
  const [tileError, setTileError] = useState(false)
  const [retryAttempt, setRetryAttempt] = useState(0)
  const mappedPlaces = useMemo(() => places.filter((place) => place.location !== null), [places])
  const hasLocations = mappedPlaces.length > 0
  const missingCount = places.length - mappedPlaces.length

  useEffect(() => {
    if (!hasLocations || !containerRef.current) return
    let active = true
    let map: Leaflet.Map | undefined
    let observer: ResizeObserver | undefined
    import('leaflet').then((leaflet) => {
      if (!active || !containerRef.current) return
      try {
        leaflet.Util.template(TILE_URL, { x: 0, y: 0, z: 0, s: 'a', r: '' })
        map = leaflet.map(containerRef.current, { scrollWheelZoom: false, zoomAnimation: false, fadeAnimation: false })
        map.attributionControl.setPrefix(false)
        map.zoomControl.getContainer()?.querySelectorAll('a').forEach((control) => control.classList.add('tap-target', '!flex', 'items-center', 'justify-center'))
        mapRef.current = map
        markerLayerRef.current = leaflet.layerGroup().addTo(map)
        let failedThisLoad = false
        const tiles = leaflet.tileLayer(TILE_URL, { attribution: ATTRIBUTION, maxZoom: 19, keepBuffer: 1 })
        tiles.on('loading', () => { failedThisLoad = false })
        tiles.on('tileerror', () => { failedThisLoad = true; if (active) setTileError(true) })
        tiles.on('load', () => { if (active && !failedThisLoad) setTileError(false) })
        tileLayerRef.current = tiles.addTo(map)
        if (typeof ResizeObserver !== 'undefined') {
          observer = new ResizeObserver(() => map?.invalidateSize())
          observer.observe(containerRef.current)
        }
        setInitError(false)
        setSession({ leaflet, map })
      } catch {
        map?.remove()
        map = undefined
        mapRef.current = null
        markerLayerRef.current = null
        tileLayerRef.current = null
        if (active) setInitError(true)
      }
    }).catch(() => { if (active) setInitError(true) })
    return () => {
      active = false
      observer?.disconnect()
      map?.remove()
      mapRef.current = null
      markerLayerRef.current = null
      tileLayerRef.current = null
    }
  }, [hasLocations, retryAttempt])

  useEffect(() => {
    if (!session || session.map !== mapRef.current || !markerLayerRef.current) return
    const { leaflet, map } = session
    const layer = markerLayerRef.current
    const focusedTitle = document.activeElement?.classList.contains('leaflet-marker-icon')
      ? document.activeElement.getAttribute('aria-label') : null
    layer.clearLayers()
    const groups = new Map<string, Place[]>()
    for (const place of mappedPlaces) {
      const key = `${place.location!.lat},${place.location!.lng}`
      groups.set(key, [...(groups.get(key) ?? []), place])
    }
    for (const group of groups.values()) {
      const selected = group.some((place) => place.id === selectedPlaceId)
      const title = group.length === 1 ? group[0].name : `${group.length} listings at this location`
      const iconContent = document.createElement('span')
      iconContent.className = cn('flex h-9 w-9 items-center justify-center rounded-full border-2 border-white text-sm font-bold text-white shadow-md',
        selected ? 'bg-brand-900 ring-4 ring-brand-300' : 'bg-brand-700')
      if (group.length > 1) iconContent.textContent = String(group.length)
      else iconContent.innerHTML = '<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path d="M20 10c0 5-8 11-8 11S4 15 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="3"/></svg>'
      const marker = leaflet.marker([group[0].location!.lat, group[0].location!.lng], {
        icon: leaflet.divIcon({ html: iconContent, className: '', iconSize: [44, 44], iconAnchor: [18, 36] }),
        title, keyboard: true, zIndexOffset: selected ? 1000 : 0,
      })
      const tooltip = document.createElement('span')
      tooltip.textContent = title
      marker.bindTooltip(tooltip, { direction: 'top', permanent: selected })
      const popup = document.createElement('div')
      for (const place of group) {
        const item = document.createElement(group.length > 1 && onSelectPlace ? 'button' : 'p')
        item.textContent = place.name
        item.className = 'block text-sm font-medium text-slate-900'
        if (item instanceof HTMLButtonElement) {
          item.type = 'button'
          item.className += ' tap-target w-full rounded-lg px-2 text-left hover:bg-slate-100'
          item.setAttribute('aria-pressed', String(place.id === selectedPlaceId))
          item.addEventListener('click', () => { onSelectPlace?.(place.id); map.closePopup(); marker.getElement()?.focus({ preventScroll: true }) })
        }
        popup.append(item)
      }
      marker.bindPopup(popup)
      marker.on('click', () => { if (group.length === 1) onSelectPlace?.(group[0].id) })
      marker.on('add', () => {
        const element = marker.getElement()
        element?.setAttribute('aria-label', title)
        element?.setAttribute('aria-pressed', String(selected))
        if (title === focusedTitle) element?.focus({ preventScroll: true })
        element?.addEventListener('keydown', (event) => {
          if (event.code === 'Space' || event.code === 'Enter') { event.preventDefault(); marker.fire('click'); marker.openPopup() }
        })
      })
      marker.addTo(layer)
    }
  }, [session, mappedPlaces, selectedPlaceId, onSelectPlace])

  useEffect(() => {
    if (!session || session.map !== mapRef.current || mappedPlaces.length === 0) return
    const points = mappedPlaces.map((place) => [place.location!.lat, place.location!.lng] as Leaflet.LatLngTuple)
    if (points.length === 1) session.map.setView(points[0], 16, { animate: false })
    else session.map.fitBounds(points, { padding: [32, 32], maxZoom: 16, animate: false })
  }, [session, mappedPlaces])

  const retry = () => {
    setTileError(false)
    if (tileLayerRef.current && !initError) tileLayerRef.current.redraw()
    else { setInitError(false); setRetryAttempt((attempt) => attempt + 1) }
  }

  return (
    <section aria-label="Public service locations" className={cn('space-y-2', className)}>
      {hasLocations ? (
        <>
          <div data-map-surface ref={containerRef} role="region" aria-label="Map of public service locations"
            className={cn('relative z-0 h-80 w-full overflow-hidden rounded-2xl border border-slate-200 bg-slate-100 text-slate-900 sm:h-96', initError && 'hidden')} />
          {(initError || tileError) && (
            <div role="alert" className="flex flex-wrap items-center justify-between gap-2 rounded-xl border border-slate-200 bg-white p-3 text-sm text-slate-800">
              <p>{initError ? 'Map unavailable.' : 'Some map tiles could not load.'} The directory remains available below.</p>
              <Button variant="secondary" onClick={retry}>Retry map</Button>
            </div>
          )}
          <p className="text-xs text-slate-600">{mappedPlaces.length} mapped {mappedPlaces.length === 1 ? 'listing' : 'listings'}.
            {missingCount > 0 && ` ${missingCount} ${missingCount === 1 ? 'listing without confirmed coordinates remains' : 'listings without confirmed coordinates remain'} available in the list.`}</p>
        </>
      ) : (
        <p className="flex items-center gap-2 rounded-xl border border-slate-200 bg-white p-4 text-sm text-slate-600">
          <MapPin size={18} aria-hidden="true" />Map location not confirmed. Listings remain available in the directory.
        </p>
      )}
      <a href="https://www.openstreetmap.org/fixthemap" target="_blank" rel="noreferrer noopener"
        className="inline-flex min-h-11 items-center text-xs font-medium text-brand-700 underline hover:text-brand-900">Report a map issue</a>
    </section>
  )
}
import { useEffect, useMemo, useState } from 'react'
import { Search } from 'lucide-react'
import { PlaceMap } from '@/components/map/PlaceMap'
import { PlaceCard } from '@/components/places/PlaceCard'
import { CATEGORY_META } from '@/components/places/categoryMeta'
import { Button } from '@/components/ui/Button'
import { Chip } from '@/components/ui/Chip'
import { TextInput } from '@/components/ui/TextInput'
import { EmptyState } from '@/components/ui/EmptyState'
import { VerificationBadge } from '@/components/verification/VerificationBadge'
import { fetchPlaces } from '@/lib/placeApi'
import type { PilotBarangay, Place, PlaceCategory, VerificationState } from '@/types'

const PILOT_CATEGORIES: PlaceCategory[] = ['government', 'health', 'education']
const BARANGAYS: PilotBarangay[] = ['Tunasan', 'Poblacion']
const VERIFICATION_FILTERS: VerificationState[] = [
  'verified', 'community_reported', 'awaiting_review', 'needs_recheck', 'disputed',
]

export function ExplorePage() {
  const [places, setPlaces] = useState<Place[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState(false)
  const [loadAttempt, setLoadAttempt] = useState(0)
  const [query, setQuery] = useState('')
  const [categoryFilter, setCategoryFilter] = useState<PlaceCategory | null>(null)
  const [barangayFilter, setBarangayFilter] = useState<PilotBarangay | null>(null)
  const [verificationFilter, setVerificationFilter] = useState<VerificationState | null>(null)
  const [selectedPlaceId, setSelectedPlaceId] = useState<string | null>(null)

  useEffect(() => {
    let active = true
    fetchPlaces()
      .then((loaded) => { if (active) setPlaces(loaded) })
      .catch(() => { if (active) setError(true) })
      .finally(() => { if (active) setLoading(false) })
    return () => { active = false }
  }, [loadAttempt])

  const filtered = useMemo(() => {
    const q = query.trim().toLowerCase()
    return places.filter((place) => {
      const matchesQuery = q.length === 0 ||
        [place.name, place.barangay, ...place.services, ...place.tags, ...place.alternateNames]
          .some((value) => value.toLowerCase().includes(q))
      return matchesQuery && (!categoryFilter || place.category === categoryFilter) &&
        (!barangayFilter || place.barangay === barangayFilter) &&
        (!verificationFilter || place.verification.state === verificationFilter)
    })
  }, [places, query, categoryFilter, barangayFilter, verificationFilter])

  return (
    <div className="space-y-5">
      <div>
        <h1 className="text-xl font-bold text-slate-900">Find public services nearby</h1>
        <p className="mt-1 text-sm text-slate-600">Government offices, public clinics, and public schools in Tunasan and Poblacion.</p>
        <p className="mt-1 text-sm text-slate-500">Pilot listings in progress. Unknown details remain marked as not confirmed.</p>
      </div>

      <TextInput icon={<Search size={16} />} placeholder="Search names, barangays, or services"
        value={query} onChange={(event) => setQuery(event.target.value)} aria-label="Search places" />

      <div role="group" aria-label="Filter by barangay" className="flex flex-wrap gap-2">
        <Chip active={barangayFilter === null} onClick={() => setBarangayFilter(null)}>Both barangays</Chip>
        {BARANGAYS.map((barangay) => (
          <Chip key={barangay} active={barangayFilter === barangay}
            onClick={() => setBarangayFilter(barangayFilter === barangay ? null : barangay)}>{barangay}</Chip>
        ))}
      </div>

      <div role="group" aria-label="Filter by category" className="-mx-4 flex gap-2 overflow-x-auto px-4 pb-1 sm:mx-0 sm:flex-wrap sm:px-0">
        <Chip active={categoryFilter === null} onClick={() => setCategoryFilter(null)}>All categories</Chip>
        {PILOT_CATEGORIES.map((category) => {
          const { label, icon: Icon } = CATEGORY_META[category]
          return (
            <Chip key={category} active={categoryFilter === category} icon={<Icon size={14} />}
              onClick={() => setCategoryFilter(categoryFilter === category ? null : category)}>{label}</Chip>
          )
        })}
      </div>

      <div role="group" aria-label="Filter by review status" className="-mx-4 flex gap-2 overflow-x-auto px-4 pb-1 sm:mx-0 sm:flex-wrap sm:px-0">
        <Chip active={verificationFilter === null} onClick={() => setVerificationFilter(null)}>All review states</Chip>
        {VERIFICATION_FILTERS.map((state) => (
          <button key={state} type="button" aria-pressed={verificationFilter === state}
            onClick={() => setVerificationFilter(verificationFilter === state ? null : state)}
            className={`tap-target rounded-full ${verificationFilter === state ? 'ring-2 ring-brand-500 ring-offset-1' : 'hover:ring-1 hover:ring-slate-300'}`}>
            <VerificationBadge state={state} />
          </button>
        ))}
      </div>

      {loading ? <p role="status" className="py-10 text-center text-sm text-slate-500">Loading the directory...</p> : error ? (
        <div role="alert">
          <EmptyState title="Directory unavailable" description="Places could not be loaded. Please try again."
            action={<Button variant="secondary" onClick={() => { setLoading(true); setError(false); setLoadAttempt((attempt) => attempt + 1) }}>Try again</Button>} />
        </div>
      ) : (
        <>
          {filtered.some((place) => place.location !== null) && (
            <PlaceMap places={filtered} selectedPlaceId={selectedPlaceId} onSelectPlace={setSelectedPlaceId} />
          )}
          <div>
            <p aria-live="polite" className="mb-2 text-sm font-medium text-slate-500">
              {filtered.length} {filtered.length === 1 ? 'place' : 'places'}
            </p>
            {filtered.length > 0 && <p className="mb-3 text-xs text-slate-500">Listings without confirmed coordinates remain available in this list.</p>}
            {filtered.length === 0 && (
              <EmptyState icon={<Search size={28} />} title={places.length === 0 ? 'No pilot listings available yet' : 'No places match your filters'}
                description={places.length === 0 ? 'Pilot listings are in progress. Please check back later.' : 'Try clearing the search text or a filter chip.'} />
            )}
            <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">
              {filtered.map((place) => <PlaceCard key={place.id} place={place} highlighted={place.id === selectedPlaceId} />)}
            </div>
          </div>
        </>
      )}
    </div>
  )
}
import { useEffect, useState } from 'react'
import { Link, useParams } from 'react-router-dom'
import { ArrowLeft, MapPin } from 'lucide-react'
import { PlaceMap } from '@/components/map/PlaceMap'
import { AccessInfoPanel } from '@/components/places/AccessInfoPanel'
import { PlaceSourcesPanel } from '@/components/places/PlaceSourcesPanel'
import { CATEGORY_META } from '@/components/places/categoryMeta'
import { VerificationBadge } from '@/components/verification/VerificationBadge'
import { FreshnessNote } from '@/components/verification/FreshnessNote'
import { Button } from '@/components/ui/Button'
import { Card } from '@/components/ui/Card'
import { EmptyState } from '@/components/ui/EmptyState'
import { fetchPlaceById } from '@/lib/placeApi'
import type { Place } from '@/types'

export function PlaceDetailPage() {
  const { placeId } = useParams<{ placeId: string }>()
  const [loadAttempt, setLoadAttempt] = useState(0)
  const [result, setResult] = useState<{ key: string; place: Place | null; error: boolean } | null>(null)
  const requestKey = `${placeId ?? ''}:${loadAttempt}`
  const loading = result?.key !== requestKey
  const place = result?.place
  const error = result?.error

  useEffect(() => {
    let active = true
    const request = placeId ? fetchPlaceById(placeId) : Promise.resolve(null)
    request.then((loaded) => { if (active) setResult({ key: requestKey, place: loaded, error: false }) })
      .catch(() => { if (active) setResult({ key: requestKey, place: null, error: true }) })
    return () => { active = false }
  }, [placeId, requestKey])

  if (loading) return <p role="status" className="py-10 text-center text-sm text-slate-500">Loading place...</p>
  if (error) return (
    <div role="alert">
      <EmptyState title="Place unavailable" description="This place could not be loaded. Please try again."
        action={<Button variant="secondary" onClick={() => setLoadAttempt((attempt) => attempt + 1)}>Try again</Button>} />
      <Link to="/" className="block text-center text-sm font-medium text-brand-700">Back to Explore</Link>
    </div>
  )
  if (!place) return (
    <EmptyState icon={<MapPin size={28} />} title="Place not found" description="This listing is unavailable or is no longer published."
      action={<Link to="/" className="text-sm font-medium text-brand-700">Back to Explore</Link>} />
  )

  const { label: categoryLabel, icon: CategoryIcon } = CATEGORY_META[place.category]

  return (
    <div className="space-y-5 pb-6">
      <Link to="/" className="inline-flex items-center gap-1.5 text-sm font-medium text-slate-600 hover:text-slate-800">
        <ArrowLeft size={16} aria-hidden="true" />Back to Explore
      </Link>
      <div>
        <div className="flex items-start gap-3">
          <div className="flex h-12 w-12 shrink-0 items-center justify-center rounded-xl bg-brand-50 text-brand-600">
            <CategoryIcon size={24} aria-hidden="true" />
          </div>
          <div className="min-w-0">
            <h1 className="text-xl font-bold leading-snug text-slate-900">{place.name}</h1>
            <p className="mt-0.5 text-sm text-slate-600">{place.barangay} · {categoryLabel}</p>
            {place.alternateNames.length > 0 && <p className="mt-1 text-xs text-slate-500">Also known as: {place.alternateNames.join(', ')}</p>}
          </div>
        </div>
        <div className="mt-3 flex flex-wrap items-center gap-2">
          <VerificationBadge state={place.verification.state} />
          {place.tags.map((tag) => <span key={tag} className="rounded-full bg-slate-100 px-2.5 py-1 text-xs text-slate-600">{tag}</span>)}
        </div>
      </div>

      {place.location ? <PlaceMap places={[place]} selectedPlaceId={place.id} /> : (
        <p className="rounded-xl bg-slate-100 p-3 text-sm text-slate-600">Map location: Not confirmed. Use the sourced address below when available.</p>
      )}

      <Card className="space-y-3 p-4">
        <h2 className="font-semibold text-slate-900">About</h2>
        <p className="text-sm text-slate-600">{place.description || 'Not confirmed'}</p>
        <dl className="text-sm">
          <dt className="font-medium text-slate-800">Address</dt>
          <dd className="mt-1 text-slate-600">{place.address || 'Not confirmed'}</dd>
        </dl>
      </Card>

      <Card className="p-4">
        <h2 className="mb-2 font-semibold text-slate-900">Services</h2>
        {place.services.length > 0 ? <ul className="list-disc space-y-1 pl-5 text-sm text-slate-600">
          {place.services.map((service) => <li key={service}>{service}</li>)}
        </ul> : <p className="text-sm text-slate-500">Not confirmed</p>}
      </Card>

      <Card className="p-4">
        <h2 className="mb-2 font-semibold text-slate-900">Public contact</h2>
        <dl className="space-y-3 text-sm">
          <div><dt className="font-medium text-slate-800">Phone</dt><dd className="mt-1 break-words text-slate-600">{place.publicPhone || 'Not confirmed'}</dd></div>
          <div><dt className="font-medium text-slate-800">Email</dt><dd className="mt-1 break-all text-slate-600">
            {place.publicEmail ? <a className="text-brand-700 underline underline-offset-2" href={`mailto:${place.publicEmail}`}>{place.publicEmail}</a> : 'Not confirmed'}
          </dd></div>
        </dl>
      </Card>

      <AccessInfoPanel access={place.access} />
      <section aria-labelledby="verification-heading">
        <h2 id="verification-heading" className="mb-2 font-semibold text-slate-900">Checks & review</h2>
        <FreshnessNote verification={place.verification} sources={place.sources} />
      </section>
      <PlaceSourcesPanel sources={place.sources} />
      <p className="text-xs text-slate-500">Pilot listings in progress for Tunasan and Poblacion. Confirm details with the office before a visit.</p>
    </div>
  )
}

